import{_ as i,p as e,q as l,Y as a}from"./framework-e1bed10d.js";const t={},n=a('<h1 id="数学类" tabindex="-1"><a class="header-anchor" href="#数学类" aria-hidden="true">#</a> 数学类</h1><h2 id="math类" tabindex="-1"><a class="header-anchor" href="#math类" aria-hidden="true">#</a> Math类</h2><h3 id="静态属性" tabindex="-1"><a class="header-anchor" href="#静态属性" aria-hidden="true">#</a> 静态属性</h3><ol><li>static final double E：比任何其他值都更接近e, 自然对数的底数。</li><li>static final double PI：比任何其他值都更接近pi，圆的周长与其直径之比</li></ol><h2 id="静态方法" tabindex="-1"><a class="header-anchor" href="#静态方法" aria-hidden="true">#</a> 静态方法</h2><ol><li>int abs(int a)、long abs(long a)、double abs(double a)、float abs(float a)：求绝对值</li><li>double floor(double a)：向下取整，返回double a的整数部分</li><li>double ceil(double a)：向上取整</li><li>double round(double a)：四舍五入</li><li>int max(int a, int b)、long max(long a, long b)、double max(double a, double b)、float max(float a, float b)：求最大值</li><li>int min(int a, int b)、long min(long a, long b)、double min(double a, double b)、float min(float a, float b)：求最小值</li></ol><h2 id="biginteger类" tabindex="-1"><a class="header-anchor" href="#biginteger类" aria-hidden="true">#</a> BigInteger类</h2><p>BigInteger类用于表示任意大小的整数，可以进行加减乘除运算，并且可以解决除不尽的问题</p><h3 id="静态常量" tabindex="-1"><a class="header-anchor" href="#静态常量" aria-hidden="true">#</a> 静态常量</h3><ol><li>static final BigInteger ONE：BigInteger常量1</li><li>static final BigInteger TEN：BigInteger常量10</li><li>static final BigInteger TWO：BigInteger常量2</li><li>static final BigInteger ZERO：BigInteger常量0</li></ol><h3 id="构造方法" tabindex="-1"><a class="header-anchor" href="#构造方法" aria-hidden="true">#</a> 构造方法</h3><ol><li>static BigInteger probablePrime(int bitLength, Random rnd)：返回一个可能是质数的正BigInteger，具有指定的bitLength</li><li>static BigInteger valueOf(long val)：返回一个 BigInteger，其值等于指定的long的值</li></ol><h3 id="实例方法" tabindex="-1"><a class="header-anchor" href="#实例方法" aria-hidden="true">#</a> 实例方法</h3><ol><li>BigInteger add(BigInteger val)：求和</li><li>BigInteger subtract(BigInteger val)：求差</li><li>BigInteger multiply(BigInteger val)：求积</li><li>BigInteger divide(BigInteger val)：求商</li><li>BigInteger mod(BigInteger m)：求余</li><li>BigInteger[] divideAndRemainder(BigInteger val)：返回包含 (this / val) 后跟 (this % val) 的两个 BigInteger 的数</li><li>BigInteger pow(int n)：求幂</li><li>BigInteger max(BigInteger val)：返回此 BigInteger 和 val 的最大值。</li><li>BigInteger min(BigInteger val)：返回此 BigInteger 和 val 的最小值</li><li>BigInteger abs()：返回一个 BigInteger，其值是此 BigInteger 的绝对值</li><li>BigInteger sqrt()：返回此 BigInteger 的整数平方根</li></ol><h3 id="取值方法" tabindex="-1"><a class="header-anchor" href="#取值方法" aria-hidden="true">#</a> 取值方法</h3><ol><li>int intValue()：将此 BigInteger 转换为 int</li><li>long longValue()：将此 BigInteger 转换为 long</li><li>float floatValue()：将此 BigInteger 转换为 float</li><li>double doubleValue()：将此 BigInteger 转换为 double</li><li>byte[] toByteArray()：返回包含此 BigInteger 的二进制补码表示的字节数组</li><li>String toString()：返回此 BigInteger 的十进制字符串表示形式。</li><li>String toString(int radix)：返回给定基数中此 BigInteger 的字符串表示形式</li></ol><h2 id="bigdecimal类" tabindex="-1"><a class="header-anchor" href="#bigdecimal类" aria-hidden="true">#</a> BigDecimal类</h2><ol><li>BigDecimal add(BigDecimal val)：求和</li><li>BigDecimal subtract(BigDecimal val)：求差</li><li>BigDecimal multiply(BigDecimal val)：求积</li><li>BigDecimal divide(BigDecimal val)：求商</li><li>BigDecimal divide(BigDecimal val, int scale, int roundingMode)：求商，scale表示精度，roundingMode表示舍入模式，可以解决除不尽的问题</li><li>BigDecimal pow(int n)：求幂</li></ol>',18),g=[n];function r(d,o){return e(),l("div",null,g)}const c=i(t,[["render",r],["__file","math.html.vue"]]);export{c as default};
